_CACHE = {}
_API_ENABLED = False
MODES = tuple(_SOURCES) + ("evidence_v2_recovery", "evidence_v3")

def set_api_enabled(enabled=False):
    """Explicit process-local safety switch. Leave False for Run All."""
    global _API_ENABLED
    _API_ENABLED = enabled is True

def restore_historical_sources(root=None):
    """Restore hash-verified embedded Python witnesses only. No data downloads/API calls.
    Existing differing files are preserved and cause a clear failure.
    """
    root = Path(root).resolve() if root is not None else Path(__file__).resolve().parent
    restored = []
    for mode, info in PROVENANCE.items():
        relative = Path(info["archive"].replace(chr(92), "/"))
        target = (root / relative).resolve()
        if relative.is_absolute() or not target.is_relative_to(root):
            raise RuntimeError("Unsafe historical source path: " + mode)
        payload = _SOURCES[mode].encode("utf-8")
        expected = info["source_sha256"]
        if hashlib.sha256(payload).hexdigest() != expected:
            raise RuntimeError("Embedded historical source checksum mismatch: " + mode)
        if target.exists():
            if target.read_bytes() != payload:
                raise RuntimeError("Historical witness differs; refusing overwrite: " + str(target))
        else:
            target.parent.mkdir(parents=True, exist_ok=True)
            try:
                with target.open("xb") as stream:
                    stream.write(payload)
            except FileExistsError:
                if target.read_bytes() != payload:
                    raise RuntimeError("Historical witness differs; refusing overwrite: " + str(target)) from None
            restored.append(str(relative))
    return restored


def get_mode(mode):
    if mode not in MODES:
        raise ValueError("Unknown experiment mode: " + str(mode))
    restore_historical_sources()
    if mode in _CACHE:
        return _CACHE[mode]
    base = "evidence_v2" if mode in ("evidence_v2_recovery", "evidence_v3") else mode
    info = PROVENANCE[base]
    source = _SOURCES[base]
    witness = Path(__file__).resolve().parent / Path(info["archive"].replace(chr(92), "/"))
    if hashlib.sha256(source.encode("utf-8")).hexdigest() != info["source_sha256"]:
        raise RuntimeError("Embedded implementation checksum mismatch: " + base)
    if hashlib.sha256(witness.read_bytes()).hexdigest() != info["source_sha256"]:
        raise RuntimeError("Historical freeze witness checksum mismatch: " + base)
    module = types.ModuleType("mast_" + mode)
    module.__file__ = str(witness)
    exec(compile(source, str(witness), "exec"), module.__dict__)
    if mode == "evidence_v2_recovery":
        module.RECOVERY_CODE_SHA256 = hashlib.sha256(_RECOVERY_SOURCE.encode("utf-8")).hexdigest()
        exec(compile(_RECOVERY_SOURCE, "notebook_step6c12_recovery", "exec"), module.__dict__)
    if mode == "evidence_v3":
        module._V2_PROMPT_FOR = module.prompt_for
        module._V3_GUIDANCE = _V3_GUIDANCE
        module.RECOVERY_CODE_SHA256 = hashlib.sha256((source + _V3_GUIDANCE + _V3_IMPLEMENTATION).encode("utf-8")).hexdigest()
        exec(compile(_V3_IMPLEMENTATION, "consolidated_evidence_v3", "exec"), module.__dict__)
    original_evaluate = module.evaluate
    def guarded_evaluate(root, dataset, allow_api=False):
        if not _API_ENABLED or not allow_api:
            raise RuntimeError("API disabled: Run All is offline. New evaluation requires explicit authorization and API enablement.")
        return original_evaluate(root, dataset, allow_api=True)
    module.evaluate = guarded_evaluate
    module.experiment_mode = mode
    module.provenance = dict(info)
    _CACHE[mode] = module
    return module

def audit_pilot(root, version="evidence_v2"):
    """Revalidate saved pilot responses offline; never edits source results."""
    root = Path(root)
    if version not in ("evidence_v2", "evidence_v3"):
        raise ValueError("Audit supports evidence_v2 or evidence_v3")
    mode = get_mode(version)
    dataset = mode.load_corpus(root, "development")
    selection = json.loads((root / "data/processed/full_corpus_step6_95118ac95142/representative_evidence_v2_pilot.json").read_text(encoding="utf-8"))
    selected = set(selection["trace_hashes"])
    records, validated, failures, folders = {}, {}, [], []
    for folder in sorted((root / "saved_results").glob("gemini_full_corpus_" + version + "_*")):
        if not folder.is_dir():
            continue
        count = 0
        for path in folder.glob("*.json"):
            if path.stem not in selected:
                continue
            h = path.stem
            if h in records:
                raise RuntimeError("Duplicate attempted trace across runs: " + h)
            record = json.loads(path.read_text(encoding="utf-8"))
            if record.get("trace_hash") != h:
                raise RuntimeError("Record identity mismatch: " + str(path))
            records[h] = record
            count += 1
            trace = dataset["traces"][h]
            expected = mode.prompt_for(trace)
            if record.get("prompt") != expected or record.get("prompt_hash") != mode.sha(expected):
                raise RuntimeError("Prompt/trace fidelity mismatch: " + h)
            try:
                candidates = record.get("raw_response", {}).get("candidates", [])
                if len(candidates) != 1 or candidates[0].get("finishReason") != "STOP":
                    raise ValueError("No complete unblocked response")
                text = "".join(part.get("text", "") for part in candidates[0].get("content", {}).get("parts", []) if not part.get("thought", False))
                predictions = mode.parse_prediction(text)
                mode.validate_quotes(predictions, trace)
                if record.get("status") != "valid":
                    raise ValueError("Saved status is not valid; manual review required")
                if predictions != record.get("predictions"):
                    raise RuntimeError("Saved prediction differs from reparse: " + h)
                validated[h] = predictions
            except ValueError as exc:
                failures.append({"trace_hash": h, "saved_status": record.get("status"), "has_saved_response": "raw_response" in record, "reason": str(exc), "record": str(path.relative_to(root))})
        if count:
            folders.append({"folder": str(folder.relative_to(root)), "attempted": count})
    refs = [r for r in dataset["references"] if r["trace_hash"] in selected]
    metrics = []
    for category in mode.DEFINITIONS:
        eligible = [r for r in refs if r["category"] == category]
        pairs, abstentions, available = [], 0, 0
        for ref in eligible:
            item = validated.get(ref["trace_hash"], {}).get(category)
            if item is None:
                continue
            available += 1
            if item["present"] is None:
                abstentions += 1
            else:
                pairs.append((ref["label"], item["present"]))
        tp = sum(y and pred for y, pred in pairs)
        tn = sum(not y and not pred for y, pred in pairs)
        fp = sum(not y and pred for y, pred in pairs)
        fn = sum(y and not pred for y, pred in pairs)
        div = lambda a, b: a / b if b else None
        metrics.append(dict(category=category, eligible=len(eligible), valid_responses=available, unavailable=len(eligible)-available, abstentions=abstentions, scored=len(pairs), response_coverage=div(available,len(eligible)), decision_coverage=div(len(pairs),len(eligible)), tp=tp,tn=tn,fp=fp,fn=fn, precision=div(tp,tp+fp),recall=div(tp,tp+fn),f1=div(2*tp,2*tp+fp+fn),ai_reference_agreement=div(tp+tn,len(pairs))))
    return {"scope":"14-case development " + version + " pilot; source labels are AI references, not human truth", "selected":len(selected),"attempted":len(records),"valid":len(validated),"invalid_or_unavailable":len(failures),"unattempted":len(selected-set(records)),"folders":folders,"failures":failures,"metrics":metrics,"semantic_review":"pending; exact quotes do not establish correct interpretation", "independent_human_review":"not recorded", "step6_complete":False}

_SETUP_ARTIFACTS = ''
_DATASET_DOWNLOADS = [{'file': 'MAD_human_labelled_dataset.json', 'bytes': 2662908, 'sha256': '30a0c4075078e9a1b8c39bc608d2b5156cc64c6bda1f6fd262786eb81ff4a286', 'url': 'https://huggingface.co/datasets/mcemri/MAST-Data/resolve/95118ac951421753cf1deb87ddea3b01e693c41b/MAD_human_labelled_dataset.json'}, {'file': 'MAD_full_dataset.json', 'bytes': 199574367, 'sha256': 'd636ac63dfc1c6af2d312e862f4b7d383b62d3898d431ccd0e7a79d21d85406f', 'url': 'https://huggingface.co/datasets/mcemri/MAST-Data/resolve/95118ac951421753cf1deb87ddea3b01e693c41b/MAD_full_dataset.json'}]

def setup_project(root, download=True):
    """Portable first-run setup. Public dataset downloads only; never Gemini calls.
    Reuses checksum-matching files and refuses to overwrite differing manifests.
    Approximately 202 MB download on a fresh machine; stdlib only.
    """
    import base64, gzip, urllib.request, os, tempfile
    root = Path(root).resolve()
    revision = "95118ac951421753cf1deb87ddea3b01e693c41b"
    # The same source-only bootstrap is also used by get_mode and clean-clone tests.
    restore_historical_sources(root)
    artifacts = json.loads(gzip.decompress(base64.b64decode(_SETUP_ARTIFACTS)))
    for relative, encoded in artifacts.items():
        target = root / relative
        payload = base64.b64decode(encoded)
        if target.exists():
            if target.read_bytes() != payload:
                raise RuntimeError("Frozen support file differs; refusing overwrite: " + relative)
        else:
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(payload)
    rawdir = root / "data/raw" / ("mast_" + revision)
    rawdir.mkdir(parents=True, exist_ok=True)
    for item in _DATASET_DOWNLOADS:
        target = rawdir / item["file"]
        if target.exists():
            if hashlib.sha256(target.read_bytes()).hexdigest() != item["sha256"]:
                raise RuntimeError("Existing dataset checksum mismatch; preserved for inspection: " + str(target))
            print("Verified existing dataset:", item["file"])
            continue
        if not download:
            raise FileNotFoundError("Dataset missing; rerun setup with download=True: " + str(target))
        print("Downloading pinned public dataset:", item["file"], "({:,} bytes)".format(item["bytes"]))
        temporary = None
        try:
            with tempfile.NamedTemporaryFile(dir=rawdir, suffix=".partial", delete=False) as output:
                temporary = Path(output.name)
                request = urllib.request.Request(item["url"], headers={"User-Agent": "MAST-notebook-setup/1.0"})
                digest = hashlib.sha256()
                with urllib.request.urlopen(request, timeout=120) as response:
                    while True:
                        chunk = response.read(1024 * 1024)
                        if not chunk:
                            break
                        output.write(chunk)
                        digest.update(chunk)
            if digest.hexdigest() != item["sha256"]:
                raise RuntimeError("Downloaded checksum mismatch: " + item["file"])
            os.replace(temporary, target)
            print("Downloaded and verified:", item["file"])
        except Exception as exc:
            raise RuntimeError("Public dataset setup failed for " + item["file"] + ". Check internet access and rerun this setup cell. " + str(exc)) from exc
        finally:
            if temporary is not None:
                temporary.unlink(missing_ok=True)
    human_path = rawdir / "MAD_human_labelled_dataset.json"
    human = json.loads(human_path.read_text(encoding="utf-8"), parse_constant=lambda value: None)  # Published NaN votes become missing votes, never labels.
    if not isinstance(human, list) or len(human) != 19:
        raise RuntimeError("Unexpected pinned human dataset structure")
    existing = sorted((root / "data/processed").glob("ground_truth_*/source_records.jsonl"))
    if existing:
        saved = [json.loads(line)["source_record"] for line in existing[-1].read_text(encoding="utf-8").splitlines() if line.strip()]
        if saved != human:
            raise RuntimeError("Existing human preprocessing differs from pinned public data; refusing silent replacement")
    else:
        dest = root / "data/processed/ground_truth_pinned_95118ac95142/source_records.jsonl"
        dest.parent.mkdir(parents=True, exist_ok=True)
        rows = [{"record_index":i,"trace_hash":hashlib.sha256(record["trace"].encode("utf-8")).hexdigest(),"source_record":record} for i,record in enumerate(human)]
        dest.write_text("".join(json.dumps(row,ensure_ascii=False)+"\n" for row in rows), encoding="utf-8")
        print("Prepared pinned human records:", len(rows))
    print("Setup complete. Public data and frozen support files verified. No Gemini requests.")
    print("Saved Gemini results are optional local artifacts; no saved results are downloaded or recreated.")
    return root

_V3_GUIDANCE = "Evidence-v3 development revision: apply these additional evidence checks to every category independently.\n1. Evidence is the recorded trace, not an assumed successful task. A written script/test/reviewer approval is not proof of execution or passing results. If tests were not visibly run, say so. Check visible expected values against displayed arithmetic; do not call a test suite comprehensive merely because multiple tests are written. Distinguish defective verification design, performed incorrect verification, and missing execution evidence using the supplied definitions; use insufficient_evidence when the defining mechanism cannot be established.\n2. A browser crash, exception or external timeout alone does not establish ill-specified termination conditions or premature termination as defined here. For present, identify the agent/system termination-condition mechanism, not just an unfinished task. A terminate/completion signal followed by continued work may support a finding only after checking whether it applied to that subtask or the whole interaction.\n3. For repetition, the two distinct quotes must demonstrate an earlier completed step and an unnecessary subsequent repetition of that completed step. Different generic tool names (scroll_down and go_back), repeated keywords, normal navigation, or distinct necessary tests are not sufficient by themselves. Explain why the later action repeats completed work rather than justified backtracking.\n4. Do not invent user constraints. A truncated user-task header ending in ... is not authority for an unstated booking, purchase, or deliverable requirement. The agent's own plan is not a substitute for the complete user request. When missing requirements prevent a category decision, use insufficient_evidence and state the missing requirement.\n5. For every absent explanation, cite what the trace actually shows and what defining behavior is not established. Do not claim tests ran, a task succeeded, or a property was comprehensively verified unless corresponding execution/results are visible. Missing evidence is not evidence of successful verification. Do not equate absent with task success.\n6. quotes must be literal substrings of BEGIN RECORDED TRACE content, including its original single/double quotation marks, apostrophes, backslashes and case. JSON escaping is permitted only to encode those SAME characters; do not normalize or paraphrase them. Prefer short, continuous, nonsensitive exact spans. Each quotes array must contain unique strings: never repeat a quote in the same array. The same span may support different categories only with category-specific reasoning. Do not copy account credentials.\n7. Upstream reference labels are not supplied and must not be assumed correct. Do not force categories to agree or infer a category merely from overall failure. Return the original fourteen keys and original decision/evidence/quotes fields only. Do not add review scores or new fields.\n"
_V3_IMPLEMENTATION = 'def prompt_for(trace):\n    original = _V2_PROMPT_FOR(trace)\n    marker = "\\nBEGIN RECORDED TRACE\\n"\n    return original.replace(marker, "\\n" + _V3_GUIDANCE + marker, 1)\n\ndef evaluate(root, dataset, allow_api=False):\n """Stable experiment directory resumes safely; existing failures are never retried."""\n if not allow_api: raise RuntimeError(\'API execution is off. Set RUN_GEMINI_14=True explicitly in the notebook after review.\')\n if dataset.get(\'split\')==\'heldout\':\n  approval=root/\'data/processed/full_corpus_step6_95118ac95142/pilot_review.json\'\n  if not approval.exists(): raise RuntimeError(\'Held-out run requires a recorded development-pilot review first.\')\n  review=json.loads(approval.read_text(encoding=\'utf-8\'))\n  if review.get(\'approved\') is not True or not review.get(\'reviewer\') or not review.get(\'notes\') or review.get(\'workflow_sha256\')!=RECOVERY_CODE_SHA256: raise RuntimeError(\'Missing or stale pilot sign-off; do not evaluate held-out traces yet.\')\n from dotenv import load_dotenv\n load_dotenv(root/\'.env\',override=True)\n if os.getenv(\'LLM_PROVIDER\',\'gemini\')!=\'gemini\': raise ValueError(\'This workflow only supports Gemini\')\n if os.getenv(\'USE_EXAMPLES\',\'false\').lower()!=\'false\': raise ValueError(\'This baseline requires USE_EXAMPLES=false\')\n model=os.getenv(\'LLM_MODEL\',os.getenv(\'GEMINI_MODEL\',\'gemini-3.5-flash-lite\'))\n if model!=\'gemini-3.5-flash-lite\': raise ValueError(\'Frozen full-corpus experiment requires gemini-3.5-flash-lite; version any model change separately.\')\n client=GeminiREST(os.getenv(\'GEMINI_API_KEY\'),model)\n config=dict(dataset_revision=dataset.get(\'dataset_revision\'),dataset_sha256=dataset.get(\'dataset_sha256\'),label_origin=dataset.get(\'label_origin\'),split=dataset.get(\'split\'),split_manifest_sha256=dataset.get(\'split_manifest_sha256\'),quarantine_sha256=dataset.get(\'quarantine_sha256\'),code_sha256=RECOVERY_CODE_SHA256,model=model,definitions=DEFINITIONS,prompt_version=\'full-corpus-fourteen-evidence-v3\',temperature=0,max_output_tokens=8192,max_input_tokens=int(os.getenv(\'MAX_INPUT_TOKENS\',\'225000\')),rpm=int(os.getenv(\'GEMINI_RPM_LIMIT\',\'15\')),tpm=int(os.getenv(\'GEMINI_INPUT_TPM_LIMIT\',\'250000\')),rpd=int(os.getenv(\'GEMINI_RPD_LIMIT\',\'500\')))\n if any(config[k]<=0 for k in (\'max_input_tokens\',\'rpm\',\'tpm\',\'rpd\')): raise ValueError(\'Limits must be positive\')\n identity=sha(json.dumps({\'config\':config,\'traces\':sorted(dataset[\'traces\']),\'references\':dataset[\'references\']},sort_keys=True))\n folder=root/\'saved_results\'/(\'gemini_full_corpus_evidence_v3_\'+identity[:16]); folder.mkdir(parents=True,exist_ok=True)\n save(folder/\'manifest.json\',dict(config=config,experiment_id=identity,source=dataset[\'source_file\'],full_traces=True,retries=0,category_headings=CATEGORY_HEADINGS,taxonomy_policy=TAXONOMY_POLICY))\n save(folder/\'reference_audit.json\',{k:v for k,v in dataset.items() if k!=\'traces\'})\n # Exclusive lock prevents concurrent notebook runs sharing this experiment.\n lock=folder/\'RUNNING.lock\'\n try: fd=os.open(lock,os.O_CREAT|os.O_EXCL|os.O_WRONLY)\n except FileExistsError: raise RuntimeError(\'Run lock exists. Check no run is active before manually removing RUNNING.lock.\')\n os.close(fd)\n try:\n  # Persist the quota ledger BEFORE each attempt; survives restarts and errors.\n  pacer=Pacer(config[\'rpm\'],config[\'tpm\'],config[\'rpd\']); ledger=root/\'saved_results/gemini_full_corpus_project_quota_ledger.json\'\n  if ledger.exists():\n   old=json.loads(ledger.read_text()); pacer.window=old[\'window\']; pacer.day=old[\'day\']\n  def call(op,payload=None,tokens=0):\n   pacer.before(tokens); save(ledger,dict(window=pacer.window,day=pacer.day))\n   return client.request(op,payload)\n  # Conservative accounting includes metadata and token-count calls in request limits.\n  model_info=call(None)\n  limit=model_info.get(\'inputTokenLimit\'); output_limit=model_info.get(\'outputTokenLimit\')\n  if not isinstance(limit,int): raise RuntimeError(\'Cannot verify model input capacity; stopping without generation\')\n  if isinstance(output_limit,int) and config[\'max_output_tokens\']>output_limit: raise RuntimeError(\'Configured output allowance exceeds model limit\')\n  save(folder/\'model_info.json\',model_info)\n  for h,trace in dataset[\'traces\'].items():\n   path=folder/(h+\'.json\')\n   if path.exists():\n    prior=json.loads(path.read_text(encoding=\'utf-8\'))\n    if prior.get(\'status\') in (\'valid\',\'blocked_input_limit\'): continue\n    raise RuntimeError(\'Existing failed or unfinished record requires manual review: \'+path.name)\n   prompt=prompt_for(trace)\n   record=dict(trace_hash=h,prompt_hash=sha(prompt),prompt=prompt,original_characters=len(trace),sent_characters=len(trace),trace_was_trimmed=False,status=\'prepared\',timestamp=datetime.now(timezone.utc).isoformat())\n   save(path,record); append_event(folder,record)\n   try:\n    contents=[{\'role\':\'user\',\'parts\':[{\'text\':prompt}]}]\n    generation={\'temperature\':config[\'temperature\'],\'maxOutputTokens\':config[\'max_output_tokens\'],\'responseMimeType\':\'application/json\',\'responseSchema\':schema()}\n    request={\'contents\':contents,\'generationConfig\':generation}\n    count=call(\'countTokens\',{\'generateContentRequest\':{\'model\':\'models/\'+model,**request}})\n    tokens=count[\'totalTokens\']; record[\'counted_input_tokens\']=tokens\n    if tokens>min(limit,config[\'max_input_tokens\'],config[\'tpm\']):\n     record[\'status\']=\'blocked_input_limit\'; save(path,record); print(h[:12],record[\'status\'],tokens); continue\n    record[\'status\']=\'generation_started\'; save(path,record); append_event(folder,record)\n    response=call(\'generateContent\',request,tokens)\n    record[\'raw_response\']=response; record[\'status\']=\'response_saved\'; save(path,record); append_event(folder,record)\n    candidates=response.get(\'candidates\',[])\n    if len(candidates)!=1 or candidates[0].get(\'finishReason\')!=\'STOP\': raise ValueError(\'Blocked, incomplete, or unexpected response\')\n    text=\'\'.join(p.get(\'text\',\'\') for p in candidates[0].get(\'content\',{}).get(\'parts\',[]) if not p.get(\'thought\',False))\n    record[\'predictions\']=parse_prediction(text); record[\'quote_locations\']=validate_quotes(record[\'predictions\'],trace); record[\'evidence_warnings\']=[c for c,v in record[\'predictions\'].items() if not v[\'evidence\'].strip()]; record[\'status\']=\'valid\'; save(path,record); append_event(folder,record)\n    print(h[:12],\'valid; full trace;\',tokens,\'input tokens\')\n   except Exception as exc:\n    record[\'status_before_error\']=record.get(\'status\'); record[\'status\']=\'error\'; record[\'error_type\']=type(exc).__name__\n    record[\'failure_stage\']=\'validation_or_save\' if \'raw_response\' in record else (\'generation_request\' if record.get(\'status_before_error\')==\'generation_started\' else \'preflight_or_request\'); record[\'error\']=(\'Response validation failed: \'+str(exc)) if record.get(\'status_before_error\')==\'response_saved\' else (str(exc) if isinstance(exc, RuntimeError) and (str(exc).startswith(\'Gemini HTTP \') or str(exc).startswith(\'Gemini transport failure (\')) else \'Request failed; no automatic retry. Inspect recovery snapshots.\')\n    save(path,record); append_event(folder,record)\n    if record.get(\'status_before_error\')==\'response_saved\' and isinstance(exc, (ValueError, KeyError, TypeError)):\n     print(h[:12], \'INVALID response preserved; no retry; continuing to next trace. Reason:\', str(exc))\n     continue\n    raise RuntimeError(\'Stopped for review; no retry. Record: \'+str(path)) from None\n finally: lock.unlink(missing_ok=True)\n return folder'


def run_step6_batch(root, split="development", max_generations=20, max_input_tokens=1000000, allow_api=False, verbose=True):
    """Bounded live extension. Same frozen v3 classifier; no generation retries.
    Development first; heldout cannot start until development has no unattempted traces.
    Human validation is never fabricated: execution authorization is recorded separately.
    """
    if not _API_ENABLED or not allow_api:
        raise RuntimeError("Live Step 6 execution is disabled by default")
    if split not in ("development", "heldout") or not 1 <= max_generations <= 20 or not 1 <= max_input_tokens <= 1000000:
        raise ValueError("Use an explicit split and a bounded batch of at most 20 generations / 1000000 input tokens")
    import os, time, inspect
    from dotenv import load_dotenv
    root = Path(root)
    mode = get_mode("evidence_v3")
    review_path = root / "data/processed/step6_consolidated_audit/step6_execution_review.json"
    review = json.loads(review_path.read_text(encoding="utf-8"))
    if review.get("execution_authorized") is not True or review.get("classifier_code_sha256") != mode.RECOVERY_CODE_SHA256:
        raise RuntimeError("Missing or stale execution scope/configuration review")
    load_dotenv(root / ".env", override=True)
    model = os.getenv("LLM_MODEL", os.getenv("GEMINI_MODEL", "gemini-3.5-flash-lite"))
    if model != "gemini-3.5-flash-lite" or os.getenv("LLM_PROVIDER", "gemini") != "gemini":
        raise RuntimeError("Provider/model differs from frozen configuration")
    data = mode.load_corpus(root, split)
    def prior_records():
        result = {}
        for folder in (root / "saved_results").glob("gemini_full_corpus_evidence_v3_*"):
            for path in folder.glob("*.json"):
                if len(path.stem) != 64:
                    continue
                record = json.loads(path.read_text(encoding="utf-8"))
                if record.get("trace_hash") != path.stem:
                    raise RuntimeError("Invalid saved trace identity: " + str(path))
                if path.stem in result:
                    raise RuntimeError("Duplicate v3 attempt requires review: " + path.stem)
                # No failed, invalid, unknown, or prepared generation is automatically resent.
                result[path.stem] = record
        return result
    prior = prior_records()
    if split == "heldout":
        development = mode.load_corpus(root, "development")
        if set(development["traces"]) - set(prior):
            raise RuntimeError("Development still has unattempted traces; heldout execution stays blocked")
    remaining = [h for h in sorted(data["traces"]) if h not in prior]
    if not remaining:
        return {"state":"no_unattempted_traces", "split":split, "generation_requests":0}
    client = mode.GeminiREST(os.getenv("GEMINI_API_KEY"), model)
    rpm = int(os.getenv("GEMINI_RPM_LIMIT", "15")); tpm = int(os.getenv("GEMINI_INPUT_TPM_LIMIT", "250000")); rpd = int(os.getenv("GEMINI_RPD_LIMIT", "500"))
    if min(rpm,tpm,rpd) <= 0:
        raise ValueError("Request limits must be positive")
    pacer = mode.Pacer(rpm,tpm,rpd)
    ledger = root / "saved_results/gemini_full_corpus_project_quota_ledger.json"
    if ledger.exists():
        saved = json.loads(ledger.read_text(encoding="utf-8")); pacer.window=saved["window"];pacer.day=saved["day"]
    class LocalQuotaPause(RuntimeError):
        pass
    def call(operation, payload=None, tokens=0):
        if sum(time.time()-stamp < 86400 for stamp in pacer.day) >= rpd:
            raise LocalQuotaPause("Local daily request cap reached; no request sent")
        pacer.before(tokens)
        mode.save(ledger, {"window":pacer.window,"day":pacer.day})
        return client.request(operation,payload)
    identity = mode.sha(json.dumps({"split":split,"classifier_code_sha256":mode.RECOVERY_CODE_SHA256,"dataset_sha256":data["dataset_sha256"]},sort_keys=True))
    folder = root / "saved_results" / ("gemini_full_corpus_evidence_v3_full_" + identity[:16] + "_" + split)
    folder.mkdir(parents=True,exist_ok=True)
    lock = root / "saved_results/STEP6_V3_FULL_RUNNING.lock"
    try: fd=os.open(lock,os.O_CREAT|os.O_EXCL|os.O_WRONLY)
    except FileExistsError: raise RuntimeError("A live full-evaluation batch may already be running")
    os.close(fd)
    result={"state":"running","split":split,"folder":str(folder),"generation_requests":0,"generated_input_tokens":0,"valid":0,"invalid":0,"blocked":0,"max_generations":max_generations,"max_input_tokens":max_input_tokens}
    try:
        metadata=call(None)
        capacity=metadata.get("inputTokenLimit")
        if not isinstance(capacity,int):raise RuntimeError("Provider input capacity could not be verified")
        if isinstance(metadata.get("outputTokenLimit"),int) and metadata["outputTokenLimit"]<8192:raise RuntimeError("Provider output capacity differs from frozen settings")
        manifest={"dataset_revision":data["dataset_revision"],"dataset_sha256":data["dataset_sha256"],"split":split,"split_manifest_sha256":data["split_manifest_sha256"],"model":model,"prompt_version":"full-corpus-fourteen-evidence-v3","classifier_code_sha256":mode.RECOVERY_CODE_SHA256,"runner_code_sha256":hashlib.sha256(inspect.getsource(run_step6_batch).encode()).hexdigest(),"temperature":0,"max_output_tokens":8192,"full_traces":True,"automatic_generation_retries":0,"label_origin":data["label_origin"],"execution_review":review,"human_correctness_validation":False}
        existing=folder/'manifest.json'
        if existing.exists():
            old=json.loads(existing.read_text(encoding='utf-8'))
            if old["classifier_code_sha256"]!=manifest["classifier_code_sha256"]:raise RuntimeError("Saved classifier identity differs")
        else:mode.save(existing,manifest)
        mode.save(folder/'model_info.json',metadata)
        for h in remaining:
            if sum(time.time()-stamp < 86400 for stamp in pacer.day) + 2 > rpd:
                result["state"]="paused_local_daily_request_cap";break
            if result["generation_requests"]>=max_generations:
                result["state"]="batch_generation_cap_reached";break
            trace=data["traces"][h];prompt=mode.prompt_for(trace)
            contents=[{"role":"user","parts":[{"text":prompt}]}]
            generation={"temperature":0,"maxOutputTokens":8192,"responseMimeType":"application/json","responseSchema":mode.schema()}
            request={"contents":contents,"generationConfig":generation}
            try:
                counted=call("countTokens",{"generateContentRequest":{"model":"models/"+model,**request}})
                tokens=counted["totalTokens"]
                if not isinstance(tokens,int) or tokens <= 0:
                    raise RuntimeError("Provider returned an invalid token count")
            except LocalQuotaPause:
                result["state"]="paused_local_daily_request_cap";break
            except (RuntimeError,KeyError,TypeError) as exc:
                result["state"]="stopped_preflight_error";result["error"]=str(exc);result["preflight_trace_hash"]=h;break
            record={"trace_hash":h,"prompt_hash":mode.sha(prompt),"prompt":prompt,"original_characters":len(trace),"sent_characters":len(trace),"trace_was_trimmed":False,"status":"prepared","timestamp":mode.datetime.now(mode.timezone.utc).isoformat(),"counted_input_tokens":tokens,"dataset_revision":data["dataset_revision"],"model":model,"prompt_version":"full-corpus-fourteen-evidence-v3"}
            record["runner_code_sha256"] = hashlib.sha256(inspect.getsource(run_step6_batch).encode()).hexdigest()
            path=folder/(h+".json")
            if tokens>min(capacity,tpm,int(os.getenv("MAX_INPUT_TOKENS","225000"))):
                record["status"]="blocked_input_limit";mode.save(path,record);mode.append_event(folder,record);result["blocked"]+=1;continue
            if result["generated_input_tokens"]+tokens>max_input_tokens:
                result["state"]="batch_input_budget_reached";result["deferred_next_trace_hash"]=h;result["deferred_counted_tokens"]=tokens;break
            record["status"]="generation_started";mode.save(path,record);mode.append_event(folder,record)
            result["generation_requests"]+=1;result["generated_input_tokens"]+=tokens
            try:
                response=call("generateContent",request,tokens)
            except RuntimeError as exc:
                record.update(status="request_error",status_before_error="generation_started",error_type=type(exc).__name__,error=str(exc),upstream_outcome="unknown",failure_stage="generation_request")
                mode.save(path,record);mode.append_event(folder,record);result["state"]="stopped_api_or_transport_error";result["error"]=str(exc);break
            record.update(raw_response=response,status="response_saved");mode.save(path,record)
            try:
                candidates=response.get("candidates",[])
                if len(candidates)!=1 or candidates[0].get("finishReason")!="STOP":raise ValueError("Blocked or incomplete response")
                text="".join(part.get("text","") for part in candidates[0].get("content",{}).get("parts",[]) if not part.get("thought",False))
                parsed=mode.parse_prediction(text);locations=mode.validate_quotes(parsed,trace)
            except (ValueError,KeyError,TypeError) as exc:
                record.update(status="invalid_response",error_type=type(exc).__name__,error=str(exc),failure_stage="response_validation");result["invalid"]+=1
            else:
                record.update(status="valid",predictions=parsed,quote_locations=locations);result["valid"]+=1
            mode.save(path,record);mode.append_event(folder,record)
            if verbose:
                print(h[:12],record["status"],tokens,"input tokens",flush=True)
            mode.save(folder/'latest_batch_progress.json',result)
        else:result["state"]="split_attempts_finished"
        mode.save(folder/'latest_batch_progress.json',result)
        return result
    except LocalQuotaPause as exc:
        result["state"]="paused_local_daily_request_cap";result["error"]=str(exc)
        mode.save(folder/'latest_batch_progress.json',result)
        return result
    except Exception as exc:
        result["state"]="stopped_unexpected_error";result["error_type"]=type(exc).__name__
        mode.save(folder/'latest_batch_progress.json',result)
        raise
    finally:lock.unlink(missing_ok=True)

def evaluation_progress(root):
    """Read current records, not a possibly old batch-boundary coverage snapshot."""
    from datetime import datetime, timezone
    root=Path(root)
    split_file=root/"data/processed/full_corpus_step6_95118ac95142/split_manifest.json"
    manifest=json.loads(split_file.read_text(encoding="utf-8"))
    lookup={r["trace_hash"]:r["split"] for r in manifest["traces"]}
    records={};latest=0;folders=[]
    for folder in sorted((root/"saved_results").glob("gemini_full_corpus_evidence_v3_*")):
        count=0
        for path in folder.glob("*.json"):
            if path.stem not in lookup:continue
            if path.stem in records:raise RuntimeError("Duplicate v3 trace attempts: "+path.stem)
            record=json.loads(path.read_text(encoding="utf-8"))
            if record.get("trace_hash")!=path.stem:raise RuntimeError("Saved trace identity mismatch")
            records[path.stem]=record;count+=1;latest=max(latest,path.stat().st_mtime)
        if count:folders.append({"folder":str(folder.relative_to(root)),"records":count})
    coverage={}
    for split in ("development","heldout"):
        hashes={h for h,s in lookup.items() if s==split};counts={}
        for h in hashes:
            status=records[h].get("status","unknown") if h in records else "unattempted"
            counts[status]=counts.get(status,0)+1
        coverage[split]={"total":len(hashes),"statuses":counts}
    status_path=root/"data/processed/step6_consolidated_audit/full_evaluation_status.json"
    worker_status=json.loads(status_path.read_text(encoding="utf-8")) if status_path.exists() else {}
    return {"coverage":coverage,"worker_state":worker_status.get("state","not started locally"),"worker_pid":worker_status.get("worker_pid"),"worker_checkpoint_at":worker_status.get("updated_at"),"latest_record_update":datetime.fromtimestamp(latest,timezone.utc).isoformat() if latest else None,"supervisor_lock_exists":(root/"saved_results/STEP6_V3_SUPERVISOR_RUNNING.lock").exists(),"batch_lock_exists":(root/"saved_results/STEP6_V3_FULL_RUNNING.lock").exists(),"folders":folders,"all_traces_accounted_for":all(x["statuses"].get("unattempted",0)==0 for x in coverage.values()),"note":"A lock/checkpoint alone does not prove the worker is alive; invalid, blocked and unknown records are not valid predictions."}

def parser_contract_checks():
    """Small standard-library-only parser checks, no API calls or files required."""
    mode=get_mode("evidence_v3")
    fixture={c:{"decision":"absent","evidence":"Synthetic record contains no observed defining failure.","quotes":[]} for c in mode.DEFINITIONS}
    parsed=mode.parse_prediction(json.dumps(fixture))
    assert len(parsed)==14 and all(x["present"] is False for x in parsed.values())
    tests=[]
    def reject(name,text):
        try:mode.parse_prediction(text)
        except ValueError:tests.append(name)
        else:raise AssertionError("Invalid answer accepted: "+name)
    missing=dict(fixture);missing.pop("step_repetition");reject("missing category",json.dumps(missing))
    extra=dict(fixture);extra["2.5"]={};reject("extra/reused numeric category code",json.dumps(extra))
    extra=dict(fixture);extra["3.3"]={};reject("extra legacy 3.3 code",json.dumps(extra))
    reject("duplicate category",'{"step_repetition":{},"step_repetition":{}}')
    reject("duplicate nested field",json.dumps(fixture).replace('"decision": "absent"','"decision": "absent", "decision": "present"',1))
    reject("non-finite JSON",'{"step_repetition": NaN}')
    bad=json.loads(json.dumps(fixture));bad["step_repetition"]["decision"]=True;reject("wrong decision type",json.dumps(bad))
    bad=json.loads(json.dumps(fixture));bad["task_derailment"]["decision"]="present";reject("unsupported positive without quote",json.dumps(bad))
    bad=json.loads(json.dumps(fixture));bad["step_repetition"].update(decision="present",quotes=["one","one"]);reject("duplicate evidence span",json.dumps(bad))
    uncertain=json.loads(json.dumps(fixture));uncertain["step_repetition"]["decision"]="insufficient_evidence"
    assert mode.parse_prediction(json.dumps(uncertain))["step_repetition"]["present"] is None
    quoted=json.loads(json.dumps(fixture));quoted["task_derailment"].update(decision="present",quotes=["literal evidence"])
    try:mode.validate_quotes(mode.parse_prediction(json.dumps(quoted)),"a different trace")
    except ValueError:tests.append("fabricated evidence quote")
    else:raise AssertionError("Fabricated quote accepted")
    return {"valid_full_answer_passed":True,"invalid_cases_rejected":tests,"abstention_preserved_not_false":True,"api_calls":0}

def print_evaluation_summary(root, batch_result=None):
    """Readable current-record totals, including after a manually launched batch."""
    from datetime import datetime, timezone
    root=Path(root)
    progress=evaluation_progress(root)
    print("CURRENT SAVED RESULTS (refreshed now)")
    for split, item in progress["coverage"].items():
        s=item["statuses"]
        print("{}: {} total | {} valid | {} unattempted".format(split.title(),item["total"],s.get("valid",0),s.get("unattempted",0)))
        other={k:v for k,v in s.items() if k not in ("valid","unattempted") and v}
        if other:
            print("  Other outcomes (not negative labels): "+", ".join("{}={}".format(k,v) for k,v in sorted(other.items())))
    print("Latest saved response/record:",progress["latest_record_update"] or "not available locally")
    locked=progress["batch_lock_exists"] or progress["supervisor_lock_exists"]
    if locked:
        print("An evaluation lock exists. Do not start another batch; a lock alone does not prove the worker is alive.")
    else:
        print("No evaluation run lock is present.")
    latest=batch_result
    latest_time=None
    if latest is None:
        candidates=list((root/"saved_results").glob("gemini_full_corpus_evidence_v3_full_*/latest_batch_progress.json"))
        if candidates:
            path=max(candidates,key=lambda x:x.stat().st_mtime)
            latest=json.loads(path.read_text(encoding="utf-8"))
            latest_time=datetime.fromtimestamp(path.stat().st_mtime,timezone.utc).isoformat()
    if latest:
        print("Latest batch:",latest.get("state","unknown"))
        if latest_time:print("Batch checkpoint time:",latest_time)
        print("  Generation attempts: {} | valid: {} | invalid: {} | blocked: {} | counted generation input tokens: {:,}".format(latest.get("generation_requests",0),latest.get("valid",0),latest.get("invalid",0),latest.get("blocked",0),latest.get("generated_input_tokens",0)))
        if latest.get("error"):
            print("  Stop reason:",latest["error"])
            print("  The interrupted trace was preserved and will not be automatically resent.")
        if latest.get("state")=="stopped_api_or_transport_error":
            print("  Evaluation stopped; it is not currently continuing in this notebook.")
    print("Full-dataset coverage complete:",progress["all_traces_accounted_for"])
    print("Validation is not correctness. Invalid, blocked and unknown outcomes are not scored as absent.")
    return progress
